Point2f ConcentricSampleDisk(const Point2f &u) {
    // Map u to [-1,1]^2
    Float phi, r;
    Float u1 = 2 * u.x - 1;
    Float u2 = 2 * u.y - 1;

    // Handle the case where both coordinates are zero
    if (u1 == 0 && u2 == 0) {
        return Point2f(0, 0);
    }

    // Shirley-Chiu concentric mapping
    if (u1 >= -u2) {
        if (u1 > 0) {
            r = u1;
            phi = (M_PI / 4) * (u2 / u1);
        } else {
            r = -u1;
            phi = (M_PI / 4) * (2 - (u2 / u1));
        }
    } else {
        if (u2 > 0) {
            r = u2;
            phi = (M_PI / 4) * (4 + (u1 / u2));
        } else {
            r = -u2;
            phi = (M_PI / 4) * (6 - (u1 / u2));
        }
    }

    return Point2f(r * std::cos(phi), r * std::sin(phi));
}

